/** Generates src/config/feature-keys.ts from supabase/seed/tier_features.csv (pnpm catalog:types). */
import { writeFileSync } from "node:fs";
import { loadCatalog } from "./seed/catalog";

const rows = loadCatalog();
const body = [
  "// GENERATED by `pnpm catalog:types` from supabase/seed/tier_features.csv. Do not edit.",
  "export const FEATURE_KEYS = [",
  ...rows.map((r) => `  "${r.feature_key}",`),
  "] as const;",
  "",
  "export type FeatureKey = (typeof FEATURE_KEYS)[number];",
  "",
].join("\n");

writeFileSync("src/config/feature-keys.ts", body);
console.log(`feature-keys.ts: ${rows.length} keys`);
